	if = {
		limit = { country_exists = DDR OR = { AND = { check_variable = { cwgg_u_phase = 5 } has_global_flag = COLDWAR_GER_1970_unity_by_detente has_country_flag = cwgg_u_rat_brd has_country_flag = cwgg_u_rat_ddr country_exists = USA country_exists = ENG country_exists = FRA country_exists = SOV check_variable = { cwgg_fp_usa = 2 } check_variable = { cwgg_fp_eng = 2 } check_variable = { cwgg_fp_fra = 2 } check_variable = { cwgg_fp_sov = 2 } check_variable = { cwgg_u_ch_1 > 0 } check_variable = { cwgg_u_ch_2 > 0 } check_variable = { cwgg_u_ch_3 > 0 } check_variable = { cwgg_u_ch_4 > 0 } check_variable = { cwgg_u_ch_5 > 0 } NOT = { has_global_flag = COLDWAR_GER_1970_unity_achieved } } AND = { has_global_flag = cwgg_german_war has_country_flag = cwgg_war_victory_ddr has_war_with = DDR DDR = { has_capitulated = yes } } } }
