	if = {
		limit = { country_exists = DDR NOT = { has_global_flag = COLDWAR_GER_1970_unity_achieved } }
		if = {
			limit = { COLDWAR_GER_1970_border_open = yes NOT = { has_global_flag = COLDWAR_GER_1970_confederation } }
