# One round of a crisis (every six months). Bonn's course is cwgg_haltung, East Berlin's is chosen now
# (by its AI, or by the human player through event COLDWAR_GGR.200).
COLDWAR_GER_1970_rv_round = {
	# IMPERIA COLD WAR — Revalidate each human order immediately before charging or resolving it.
	if = { limit = { is_ai = no check_variable = { cwgg_brd_order_ready > 0 } NOT = { OR = { AND = { check_variable = { cwgg_haltung = 1 } COLDWAR_GER_1970_rv_can_stance_wait = yes } AND = { check_variable = { cwgg_haltung = 2 } COLDWAR_GER_1970_rv_can_stance_deescalate = yes } AND = { check_variable = { cwgg_haltung = 3 } COLDWAR_GER_1970_rv_can_stance_firm = yes } AND = { check_variable = { cwgg_haltung = 4 } COLDWAR_GER_1970_rv_can_stance_pressure = yes } AND = { check_variable = { cwgg_haltung = 5 } COLDWAR_GER_1970_rv_can_stance_allies = yes } AND = { check_variable = { cwgg_haltung = 6 } COLDWAR_GER_1970_rv_can_stance_secret = yes } AND = { check_variable = { cwgg_haltung = 7 } COLDWAR_GER_1970_rv_can_stance_mobilise = yes } } } } hidden_effect = { set_variable = { cwgg_brd_order_ready = 0 } } }
	if = { limit = { DDR = { is_ai = no } check_variable = { cwgg_ddr_order_ready > 0 } NOT = { OR = { AND = { check_variable = { cwgg_ddr_wahl = 1 } } AND = { check_variable = { cwgg_ddr_wahl = 2 } } AND = { check_variable = { cwgg_ddr_wahl = 3 } check_variable = { cwgg_init_ddr > 0 } } AND = { check_variable = { cwgg_ddr_wahl = 4 } check_variable = { cwgg_init_ddr > 0 } country_exists = SOV } AND = { check_variable = { cwgg_ddr_wahl = 5 } check_variable = { cwgg_init_ddr > 0 } } } } } hidden_effect = { set_variable = { cwgg_ddr_order_ready = 0 } } hidden_effect = { set_variable = { cwgg_ddr_wahl = 0 } } }
	if = { limit = { check_variable = { cwgg_krise_typ > 0 } check_variable = { cwgg_countdown = 0 }
